};

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;

  return `{${Object.keys(value as Record<string, unknown>)
    .sort()
    .map(
      (key) =>
        `${JSON.stringify(key)}:${stableStringify((value as Record<string, unknown>)[key])}`,
    )
    .join(",")}}`;
}

function sha256(value: string) {
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;
}

function jsonObject(value: Record<string, unknown>): Prisma.InputJsonObject {
  return value as Prisma.InputJsonObject;
}

function iso(value: Date | string | null | undefined) {
  return value ? new Date(value).toISOString() : null;
}

function decimalNumber(
  value: Prisma.Decimal | number | string | null | undefined,
) {
  if (value === null || value === undefined) return null;
  if (typeof value === "number") return value;
  return Number(value);
}

function metadataRecord(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value as Record<string, unknown>;
}

function stringOrNull(value: unknown) {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function booleanOrNull(value: unknown) {
  return typeof value === "boolean" ? value : null;
}

function numberOrNull(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function stringArray(value: unknown) {
  return Array.isArray(value)
    ? value
        .filter((entry): entry is string => typeof entry === "string")
        .map((entry) => entry.trim())
        .filter(Boolean)
    : [];
}

function redactClosePackEvidenceRef(value?: string | null) {
  if (!value) return null;
  return `redacted:${createHash("sha256").update(value).digest("hex").slice(0, 12)}`;
}

function sensitiveMetadataKey(key: string) {
  const compact = key.toLowerCase().replace(/[^a-z0-9]/g, "");
  return (
    compact.includes("secret") ||
    compact.includes("token") ||
    compact.includes("password") ||
    compact.includes("credential") ||
    compact.includes("apikey") ||
    compact.includes("authorization") ||
    compact === "auth" ||
    compact === "authheader" ||
    compact === "payload" ||
    compact.includes("providerpayload") ||
    compact.includes("rawpayload") ||
    compact.includes("rawprovider") ||
    compact.includes("authoritypayload") ||
    compact.includes("auditpayload") ||
    compact.includes("salaryamount") ||
    compact.includes("personlevelamounts") ||
    compact.includes("employeeid") ||
    compact.includes("paymentdestination")
  );
}

function redactedMetadataValue(value: unknown) {
  if (value === null || value === undefined) return null;
  if (typeof value === "string" && value.trim()) {
    return redactClosePackEvidenceRef(value);
  }
  if (Array.isArray(value)) return value.length ? "redacted" : [];
  if (typeof value === "object") return "redacted";
  return "redacted";
}

function redactSensitiveMetadata(
  value: unknown,
  parentKey = "",
  depth = 0,
): unknown {
  if (sensitiveMetadataKey(parentKey)) return redactedMetadataValue(value);
  if (value === null || value === undefined) return value;
  if (depth > 8) return "redacted";
  if (Array.isArray(value)) {
    return value.map((entry) =>
      redactSensitiveMetadata(entry, parentKey, depth + 1),
    );
  }
  if (typeof value !== "object") return value;

  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
      key,
      redactSensitiveMetadata(entry, key, depth + 1),
    ]),
  );
}

function closePackTrustLevelFromMetadata(value: unknown) {
  const trustLevel = stringOrNull(metadataRecord(value).trustLevel);
  return trustLevel && TRUST_LEVEL_RANK[trustLevel] !== undefined
    ? trustLevel
    : null;
}

function closePackTrustRank(value: unknown) {
  const trustLevel = closePackTrustLevelFromMetadata(value);
  return trustLevel ? TRUST_LEVEL_RANK[trustLevel] ?? -1 : -1;
}

function auditPayloadAfter(row: PilotAuditRow | null) {
  const changes = metadataRecord(row?.changes);
  const after = metadataRecord(changes.after);
  return Object.keys(after).length > 0 ? after : changes;
}

function dateOrNull(value: Date | string | null | undefined) {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function sourceMetadataForInput(
  input: CloseCertificationInvalidationInput,
): CloseCertificationInvalidationSourceMetadata {
  if (input.sourceCode && input.sourceCode !== "CUSTOM")
    return CLOSE_CERTIFICATION_INVALIDATION_SOURCES[input.sourceCode];

  const matchedSource = Object.values(
    CLOSE_CERTIFICATION_INVALIDATION_SOURCES,
  ).find(
    (source) =>
      source.sourceModel === input.sourceModel &&
      source.sourceEventName === input.sourceEventName,
  );
  if (matchedSource) return matchedSource;

  return {
    sourceCode: input.sourceCode ?? "CUSTOM",
    ring: "CUSTOM",
    domain: "custom",
    sourceModel: input.sourceModel,
    sourceTable: null,
    sourceEventName: input.sourceEventName,
    closeImpact: "CERTIFIED_CLOSE_EVIDENCE_STALE",
  };
}

function sourcePayload(source: CloseCertificationInvalidationSourceMetadata) {
  return {
    sourceCode: source.sourceCode,
    ring: source.ring,
    domain: source.domain,
    sourceModel: source.sourceModel,
    sourceTable: source.sourceTable,
    sourceEventName: source.sourceEventName,
    closeImpact: source.closeImpact,
  };
}

function stringField(value: Record<string, unknown> | null, key: string) {
  const raw = value?.[key];
  return typeof raw === "string" && raw.trim() ? raw : null;
}

function statutoryCertificationBlockerMetadata() {
  return {
    systemEvidenceStatus: "SYSTEM_EVIDENCE_ONLY",
    statutoryReadinessStatus: "STATUTORY_BLOCKED",
    statutoryAuthorityStatus: "AUTHORITY_NOT_CONFIGURED",
    blockers: [
      "AUTHORITY_NOT_CONFIGURED",
      "REQUIRES_EXPERT_REVIEW",
      "COUNTRY_PACK_UNVERIFIED",
      "ADAPTER_SANDBOX_ONLY",
    ],
  };
}

function inventoryAnnexFromResult(
  run: NonNullable<Awaited<ReturnType<typeof loadCloseRunForPack>>>,
  result: InventoryClass3ReconciliationResult,
  asOf: string,
) {
  return {
    organizationId: run.organizationId,
    accountingPeriodId: run.periodId,
    asOf,
    valuationMethod: "WEIGHTED_AVERAGE",
    sourceCounts: result.sourceCounts,
    class3LedgerBalanceTotal: result.ledgerClass3Value,
    inventorySubledgerValueTotal: result.inventoryValue,
    mismatchAmount: result.driftAmount,
    sourceHash: result.evidenceHash,
    evidenceHashVersion: result.evidenceHashVersion,
    observationHash: result.reportHash,
    recordedThrough: result.recordedThrough,
    blockerStatus:
      result.status === "PASSED" ? "PASSED" : "INVENTORY_VALUATION_MISMATCH",
    failures: result.failures.map((failure) => ({
      type: failure.type,
      severity: failure.severity,
      message: failure.message,
      metadata: failure.metadata,
    })),
  };
}

function savedInventoryAnnex(
  run: NonNullable<Awaited<ReturnType<typeof loadCloseRunForPack>>>,
) {
  const raw = metadataRecord(run.metadata).inventoryValuationAnnex;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  return raw as Record<string, unknown>;
}

function savedInventoryEvidence(
  run: NonNullable<Awaited<ReturnType<typeof loadCloseRunForPack>>>,
) {
  return (
    run.evidenceItems.find(
      (item) => item.sourceType === "InventoryValuationAnnex",
    ) ?? null
  );
}

function savedPayrollFinanceForecastProof(
  run: NonNullable<Awaited<ReturnType<typeof loadCloseRunForPack>>>,
) {
  const raw = metadataRecord(run.metadata).payrollFinanceForecastProof;
  const savedProof = redactedPayrollFinanceForecastProof(raw);
  if (savedProof) return savedProof;

  const evidenceMetadata = run.evidenceItems.find(
    (item) => item.sourceType === "PayrollFinanceForecastProof",
  )?.metadata;
  return redactedPayrollFinanceForecastProof(evidenceMetadata);
}

function redactedPayrollFinanceForecastProof(value: unknown) {
  const raw = metadataRecord(value);
  if (Object.keys(raw).length === 0) return null;
  const blockerCodes = stringArray(raw.blockerCodes);

  return {
    status: stringOrNull(raw.status),
    authoritative: booleanOrNull(raw.authoritative),
    reasonCode: stringOrNull(raw.reasonCode),
    message: stringOrNull(raw.message),
    horizonStart: stringOrNull(raw.horizonStart),
    horizonEnd: stringOrNull(raw.horizonEnd),
    upcomingNetPayAmount: numberOrNull(raw.upcomingNetPayAmount),
    upcomingStatutoryLiabilityAmount: numberOrNull(
      raw.upcomingStatutoryLiabilityAmount,
    ),
    totalUpcomingAmount: numberOrNull(raw.totalUpcomingAmount),
    payrollPeriodCount: numberOrNull(raw.payrollPeriodCount),
    payrollRunCount: numberOrNull(raw.payrollRunCount),
    paymentBatchCount: numberOrNull(raw.paymentBatchCount),
    declarationCount: numberOrNull(raw.declarationCount),
    sourceLinkCount: numberOrNull(raw.sourceLinkCount),
    evidenceHashCount: numberOrNull(raw.evidenceHashCount),
    certifiedInputRunCount: numberOrNull(raw.certifiedInputRunCount),
    certifiedInputProofHashCount: numberOrNull(
      raw.certifiedInputProofHashCount,
    ),
    registerToLedgerRunCount: numberOrNull(raw.registerToLedgerRunCount),
    nextPayDate: stringOrNull(raw.nextPayDate),
    nextDeclarationDueDate: stringOrNull(raw.nextDeclarationDueDate),
    blockerCount: Math.max(
      blockerCodes.length,
      Array.isArray(raw.blockers) ? raw.blockers.length : 0,
    ),
    blockerCodes,
    sourceHash: stringOrNull(raw.sourceHash),
    generatedAt: stringOrNull(raw.generatedAt),
    sourceModules: stringArray(raw.sourceModules),
    personLevelAmounts: "redacted",
    personLevelAmountsRedacted: true,
    proofDisclosure: "AGGREGATE_HASH_COUNTS_ONLY",
  };
}

function redactedCloseRunMetadata(value: unknown) {
  const metadata = metadataRecord(value);
  const redactedMetadata = redactSensitiveMetadata(metadata) as Record<
    string,
    unknown
  >;
  const payrollFinanceForecastProof = redactedPayrollFinanceForecastProof(
    metadata.payrollFinanceForecastProof,
  );
  return payrollFinanceForecastProof
    ? { ...redactedMetadata, payrollFinanceForecastProof }
    : redactedMetadata;
}

function pilotCertificationEvidenceFromAudit(
  row: PilotAuditRow | null,
  closePeriodPayrollRunCount: number,
): PilotCertificationEvidence {
  const payload = auditPayloadAfter(row);
  const proofContinuity = metadataRecord(payload.proofContinuity);
  const signoff = metadataRecord(payload.signoff);
  const blockers = Array.isArray(payload.blockers) ? payload.blockers : [];
  const blockerCodes = blockers
    .map((blocker) => stringOrNull(metadataRecord(blocker).code))
    .filter((code): code is string => Boolean(code));
  const missingSignoffRoles = stringArray(signoff.missingRoles);
  const annex: PilotCertificationAnnex = {
    status: stringOrNull(payload.status),
    auditLogRef: redactClosePackEvidenceRef(row?.id),
    payrollRunRef: redactClosePackEvidenceRef(row?.entityId),
    certificateHash: stringOrNull(payload.certificateHash),
    generatedAt: stringOrNull(payload.generatedAt),
    blockerCount: blockers.length,
    blockerCodes,
    missingSignoffRoles,
    expectedAdapterChaosReleaseGateHash: stringOrNull(
      proofContinuity.expectedAdapterChaosReleaseGateHash,
    ),
    proofBackfillAdapterChaosMatchesExpected: booleanOrNull(
      proofContinuity.proofBackfillAdapterChaosMatchesExpected,
    ),
    closePeriodPayrollRunCount,
  };
  const certificationBlockers: string[] = [];

  if (closePeriodPayrollRunCount === 0) {
    certificationBlockers.push(
      "No payroll run belongs to this close period for pilot-cycle certification.",
    );
  } else if (!row) {
    certificationBlockers.push(
      "Persisted payroll pilot-cycle certification evidence is missing for this close period.",
    );
  }

  if (row) {
    if (annex.status !== PILOT_CERTIFIED_STATUS) {
      certificationBlockers.push(
        "Persisted payroll pilot-cycle certification is not certified for production release review.",
      );
    }
    if (!annex.certificateHash) {
      certificationBlockers.push(
        "Persisted payroll pilot-cycle certification is missing a certificate hash.",
      );
    }
    if (annex.blockerCount > 0) {
      certificationBlockers.push(
        `${annex.blockerCount} payroll pilot-cycle certification blocker(s) remain open.`,
      );
    }
    if (annex.missingSignoffRoles.length > 0) {
      certificationBlockers.push(
        `Payroll pilot-cycle certification is missing signoff from ${annex.missingSignoffRoles.join(", ")}.`,
      );
    }
    if (!annex.expectedAdapterChaosReleaseGateHash) {
      certificationBlockers.push(
        "Payroll pilot-cycle certification is missing adapter chaos release-gate proof.",
      );
    }
    if (annex.proofBackfillAdapterChaosMatchesExpected !== true) {
      certificationBlockers.push(
        "Payroll pilot-cycle proof-backfill adapter chaos continuity is not proven.",
      );
    }
  }

  return { annex, certificationBlockers };
}

async function loadPilotCertificationEvidenceForCloseRun(
  run: NonNullable<Awaited<ReturnType<typeof loadCloseRunForPack>>>,
  tx: Prisma.TransactionClient | typeof db,
): Promise<PilotCertificationEvidence> {
  // Applicability follows retained period records, never module selection. Include
  // overlapping dates so a missing/wrong accounting link cannot hide payroll.
  const periods = await tx.payrollPeriod.findMany({
    where: {
      organizationId: run.organizationId,
      OR: [
        { accountingPeriodId: run.periodId },
        { periodStart: { lte: run.period.endDate }, periodEnd: { gte: run.period.startDate } },
      ],
    },
    select: { id: true, accountingPeriodId: true },
    orderBy: { id: "asc" },
  });
  if (periods.length === 0) {
    return {
      annex: {
        ...pilotCertificationEvidenceFromAudit(null, 0).annex,
        status: "NOT_APPLICABLE",
        applicability: "NO_RECORDED_PAYROLL_PERIOD",
        closePeriodPayrollPeriodCount: 0,
        runCertificates: [],
      },
      certificationBlockers: [],
    };
  }
  const payrollRuns = await tx.payrollRun.findMany({
    where: {
      organizationId: run.organizationId,
      deletedAt: null,
      payrollPeriod: { organizationId: run.organizationId, id: { in: periods.map(period => period.id) } },
    },
    select: { id: true, payrollPeriodId: true },
    orderBy: { id: "asc" },
  });
  const audits = payrollRuns.length ? await tx.auditLog.findMany({
    where: {
      organizationId: run.organizationId,
      entityType: PILOT_ENTITY_TYPE,
      action: PILOT_AUDIT_ACTION,
      entityId: { in: payrollRuns.map(payrollRun => payrollRun.id) },
    },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    select: { id: true, entityId: true, changes: true, createdAt: true },
  }) : [];
  const latestByRun = new Map<string, PilotAuditRow>();
  for (const audit of audits) if (!latestByRun.has(audit.entityId)) latestByRun.set(audit.entityId, audit);
  const evidence = payrollRuns.map(payrollRun => {
    const result = pilotCertificationEvidenceFromAudit(latestByRun.get(payrollRun.id) ?? null, 1);
    result.annex.payrollRunRef = redactClosePackEvidenceRef(payrollRun.id);
    return result;
  });
  const certificationBlockers = evidence.flatMap((item, index) =>
    item.certificationBlockers.map(blocker => "Payroll run " + (index + 1) + ": " + blocker),
  );
  const periodsWithRuns = new Set(payrollRuns.map(payrollRun => payrollRun.payrollPeriodId));
  const missingRuns = periods.filter(period => !periodsWithRuns.has(period.id)).length;
  if (missingRuns > 0) certificationBlockers.push(
    missingRuns + " payroll period(s) have no retained payroll run for pilot-cycle certification.",
  );
  const unlinkedPeriods = periods.filter(period => period.accountingPeriodId !== run.periodId).length;
  if (unlinkedPeriods > 0) certificationBlockers.push(
    unlinkedPeriods + " overlapping payroll period(s) require a matching accounting-period link before certification.",
  );
  return {
    annex: {
      ...(evidence.length === 1 ? evidence[0].annex : pilotCertificationEvidenceFromAudit(null, payrollRuns.length).annex),
      status: certificationBlockers.length > 0 ? "BLOCKED" : PILOT_CERTIFIED_STATUS,
      applicability: "REQUIRED",
      closePeriodPayrollPeriodCount: periods.length,
      closePeriodPayrollRunCount: payrollRuns.length,
      blockerCount: certificationBlockers.length,
      runCertificates: evidence.map(item => item.annex),
    },
    certificationBlockers,
  };
}

async function evaluateInventoryAnnexFreshness(
  run: NonNullable<Awaited<ReturnType<typeof loadCloseRunForPack>>>,
  tx: Prisma.TransactionClient | typeof db,
  detectedAt: string,
): Promise<InventoryAnnexFreshness> {
  const savedAnnex = savedInventoryAnnex(run);
  const inventoryEvidence = savedInventoryEvidence(run);
  const previousEvidenceHash =
    stringField(savedAnnex, "sourceHash") ??
    inventoryEvidence?.sourceHash ??
    null;
  const sourceId = run.periodId;

  if (!savedAnnex || !inventoryEvidence || !previousEvidenceHash) {
    return {
      status: "MISSING",
      sourceModel: "InventoryValuationAnnex",
      sourceId,
      sourceEventName: "inventory.valuation.annex.checked",
      staleReason:
        "Inventory valuation annex evidence is missing from the persisted close run.",
      previousEvidenceHash,
      newEvidenceHash: null,
      savedAnnex,
      currentAnnex: null,
      certificationBlocker: "Inventory valuation annex evidence is missing.",
      detectedAt,
    };
  }

  if (savedAnnex.evidenceHashVersion !== 1) {
    return {
      status: "MISSING", sourceModel: "InventoryValuationAnnex", sourceId,
      sourceEventName: "inventory.valuation.annex.checked",
      staleReason: "Inventory valuation evidence predates the source-fingerprint contract. Run a new close assessment.",
      previousEvidenceHash, newEvidenceHash: null, savedAnnex, currentAnnex: null,
      certificationBlocker: "Inventory valuation evidence must be regenerated with a current source fingerprint.",
      detectedAt,
    };
  }

  if (stringField(savedAnnex, "blockerStatus") !== "PASSED") {
    return {
      status: "BLOCKED",
      sourceModel: "InventoryValuationAnnex",
      sourceId,
      sourceEventName: "inventory.valuation.annex.checked",
      staleReason: `Saved inventory valuation annex status is ${stringField(savedAnnex, "blockerStatus") ?? "unknown"}.`,
      previousEvidenceHash,
      newEvidenceHash: previousEvidenceHash,
      savedAnnex,
      currentAnnex: null,
      certificationBlocker: "Inventory valuation annex is blocked.",
      detectedAt,
    };
  }

  let current: InventoryClass3ReconciliationResult;
  try {
    current = await reconcileInventoryClass3(
      {
        organizationId: run.organizationId,
        periodId: run.periodId,
        currency: run.organization.currency ?? "XAF",
      },
      tx,
    );
  } catch {
    const message = "Inventory valuation annex could not be refreshed.";
    return {
      status: "UNAVAILABLE",
      sourceModel: "InventoryValuationAnnex",
      sourceId,
      sourceEventName: "inventory.valuation.annex.checked",
      staleReason: message,
      previousEvidenceHash,
      newEvidenceHash: null,
      savedAnnex,
      currentAnnex: null,
      certificationBlocker:
        "Inventory valuation annex freshness could not be verified.",
      detectedAt,
    };
  }

  const currentAnnex = inventoryAnnexFromResult(run, current, detectedAt);
  if (current.status !== "PASSED") {
    return {
      status: "BLOCKED",
      sourceModel: "InventoryValuationAnnex",
      sourceId,
      sourceEventName: "inventory.valuation.annex.checked",
      staleReason:
        current.failures[0]?.message ??
        "Current inventory valuation reconciliation is blocked.",
      previousEvidenceHash,
      newEvidenceHash: current.evidenceHash,
      savedAnnex,
      currentAnnex,
      certificationBlocker:
        "Current inventory valuation reconciliation is blocked.",
      detectedAt,
    };
  }

  if (
    previousEvidenceHash !== current.evidenceHash ||
    inventoryEvidence.sourceHash !== current.evidenceHash
  ) {
    return {
      status: "STALE",
      sourceModel: "InventoryValuationAnnex",
      sourceId,
      sourceEventName: "inventory.valuation.annex.checked",
      staleReason:
        "Inventory valuation annex hash changed after close readiness was captured.",
      previousEvidenceHash,
      newEvidenceHash: current.evidenceHash,
      savedAnnex,
      currentAnnex,
      certificationBlocker: "Inventory valuation annex evidence is stale.",
      detectedAt,
    };
  }

  return {
    status: "FRESH",
    sourceModel: "InventoryValuationAnnex",
    sourceId,
    sourceEventName: "inventory.valuation.annex.checked",
    staleReason: null,
    previousEvidenceHash,
    newEvidenceHash: current.evidenceHash,
    savedAnnex,
    currentAnnex,
    certificationBlocker: null,
    detectedAt,
  };
}

function requireFreshControl(control: ExportClosePackControl, now: Date) {
  const lastAuthAt = control.lastAuthAt
    ? new Date(control.lastAuthAt).getTime()
    : 0;
  if (!lastAuthAt || now.getTime() - lastAuthAt > 5 * 60 * 1000) {
    throw new BusinessRuleError(
      "Fresh authentication is required to certify a close pack.",
      "FRESH_AUTH_REQUIRED",
    );
  }
}

function assertExportPermission(
  mode: ClosePackExportMode,
  control: ExportClosePackControl,
) {
  const permission =
    mode === "CERTIFIED"
      ? "accounting.close.certify"
      : "accounting.close.export";
  if (!hasRbacPermission(control.actorPermissions ?? [], permission)) {
    throw new BusinessRuleError(`Missing ${permission} permission.`);
  }
}

function exportMode(input: ExportClosePackInput): ClosePackExportMode {
  return input.mode ?? "DRAFT_NOT_CERTIFIED";
}

function certificationLimitations(mode: ClosePackExportMode) {
  return mode === "CERTIFIED"
    ? [
        "System-certified close pack only; statutory filings still require qualified expert validation.",
        "Automatic recertification triggers are limited to the captured close-run snapshot in this slice.",
      ]
    : [
        "Draft close pack is not certified and may include unresolved blockers.",
        "System evidence pack only; statutory filings still require qualified expert validation.",
      ];
}

function certificationBlockers(
  run: Awaited<ReturnType<typeof loadCloseRunForPack>>,
  mode: ClosePackExportMode,
  inventoryFreshness?: InventoryAnnexFreshness,
  pilotCertification?: PilotCertificationEvidence,
) {
  if (!run) return ["Close run not found."];

  const blockers: string[] = [];
  const openHighRiskFindings = run.findings.filter(
    (finding) =>
      OPEN_FINDING_STATUSES.includes(
        finding.status as (typeof OPEN_FINDING_STATUSES)[number],
      ) &&
      (finding.severity === CloseFindingSeverity.CRITICAL ||
        finding.severity === CloseFindingSeverity.HIGH),
  );
  const failedHighRiskChecklist = run.checklistItems.filter(
    (item) =>
      HIGH_RISK_CHECKLIST_STATUSES.includes(
        item.status as (typeof HIGH_RISK_CHECKLIST_STATUSES)[number],
      ) &&
      (item.severity === CloseFindingSeverity.CRITICAL ||
        item.severity === CloseFindingSeverity.HIGH),
  );
  const availableEvidence = run.evidenceItems.filter((item) => item.available);
  const unsignedReconciliationEvidence = run.evidenceItems.filter(
    (item) =>
      item.evidenceType === CloseEvidenceType.RECONCILIATION_CERTIFICATE &&
      (!item.sourceHash || item.provenance !== "POSTED"),
  );
  const unavailableCriticalEvidence = run.evidenceItems.filter(
    (item) =>
      !item.available && CRITICAL_EVIDENCE_TYPES.includes(item.evidenceType),
  );
  const minimumTrustLevel = mode === "CERTIFIED" ? "T4" : "T3";
  const trustLevel = closePackTrustLevelFromMetadata(run.metadata);
  const trustRank = closePackTrustRank(run.metadata);

  if (metadataRecord(metadataRecord(run.metadata).staleState).status === "EVIDENCE_STALE")
    blockers.push("A recorded change invalidated close certification evidence. Run a new close assessment.");
  if (run.status !== CloseRunStatus.READY)
    blockers.push(`Close run status is ${run.status}, not READY.`);
  if (trustRank < TRUST_LEVEL_RANK[minimumTrustLevel])
    blockers.push(
      `${mode === "CERTIFIED" ? "Certified" : "Draft"} close pack requires at least ${minimumTrustLevel} data trust; current close run trust level is ${trustLevel ?? "missing"}.`,
    );
  if (run.criticalBlockerCount > 0)
    blockers.push(
      `${run.criticalBlockerCount} critical blocker(s) remain open.`,
    );
  if (run.highBlockerCount > 0)
    blockers.push(
      `${run.highBlockerCount} high-severity blocker(s) remain open.`,
    );
  if (openHighRiskFindings.length > 0)
    blockers.push(
      `${openHighRiskFindings.length} open high-risk finding(s) block certification.`,
    );
  if (failedHighRiskChecklist.length > 0)
    blockers.push(
      `${failedHighRiskChecklist.length} high-risk checklist gate(s) failed or unavailable.`,
    );
  if (availableEvidence.length === 0)
    blockers.push(
      "No available evidence items were captured for this close run.",
    );
  if (unsignedReconciliationEvidence.length > 0)
    blockers.push(
      `${unsignedReconciliationEvidence.length} reconciliation certificate reference(s) are unsigned or missing hashes.`,
    );
  if (unavailableCriticalEvidence.length > 0)
    blockers.push(
      `${unavailableCriticalEvidence.length} critical evidence reference(s) are unavailable.`,
    );
  if (inventoryFreshness?.certificationBlocker)
    blockers.push(inventoryFreshness.certificationBlocker);
  if (pilotCertification?.certificationBlockers.length)
    blockers.push(...pilotCertification.certificationBlockers);

  return blockers;
}

async function lockCloseRunEvidenceInTx(
  tx: Prisma.TransactionClient,
  organizationId: string,
  closeRunId: string,
) {
  // Source writers take their domain locks before reaching this boundary. The
  // certifier only reads those sources; both paths lock the run before exports.
  const rows = await tx.$queryRaw<{ id: string }[]>(Prisma.sql`
    SELECT "id" FROM "close_runs"
    WHERE "organizationId" = ${organizationId} AND "id" = ${closeRunId}
    FOR NO KEY UPDATE
  `);
  if (rows.length === 0) throw new NotFoundError("Close run not found");
}

async function loadCloseRunForPack(
  organizationId: string,
  closeRunId: string,
  tx: Prisma.TransactionClient | typeof db = db,
) {
  return tx.closeRun.findFirst({
    where: { id: closeRunId, organizationId, period: { organizationId } },
    include: {
      organization: {
        select: {
          id: true,
          name: true,
          country: true,
          currency: true,
          timezone: true,
          defaultLocale: true,
        },
      },
      period: {
        select: {
          id: true,
          name: true,
          status: true,
          startDate: true,
          endDate: true,
        },
      },
      checklistItems: { orderBy: [{ domain: "asc" }, { key: "asc" }] },
      findings: { orderBy: [{ severity: "desc" }, { createdAt: "asc" }] },
      evidenceItems: {
        orderBy: [{ evidenceType: "asc" }, { createdAt: "asc" }],
      },
      comments: { orderBy: { createdAt: "asc" } },
      reviews: { orderBy: { createdAt: "asc" } },
    },
  });
}

async function loadClosePackAuditExcerpt(
  tx: Prisma.TransactionClient,
  organizationId: string,
  closeRunId: string,
) {
  return tx.ledgerAuditEvent.findMany({
    where: {
      organizationId,
      OR: [
        { resourceType: "CloseRun", resourceId: closeRunId },
        { resourceType: "ClosePackExport" },
        {
          action: {
            in: [
              "CLOSE_ASSURANCE_RUN_COMPLETED",
              "CLOSE_ASSURANCE_RUN_BLOCKED",
              "CLOSE_ASSURANCE_FINDING_ASSIGNED",
              "CLOSE_ASSURANCE_FINDING_RESOLVED",
              "CLOSE_ACCOUNTANT_REVIEW_UPDATED",
              "CLOSE_CERTIFICATION_EVIDENCE_STALE",
            ],
          },
        },
      ],
    },
    orderBy: { createdAt: "desc" },
    take: 12,
    select: {
      id: true,
      action: true,
      actorId: true,
      resourceType: true,
      resourceId: true,
      message: true,
      metadata: true,
      createdAt: true,
    },
  });
}

type CloseRunForPack = NonNullable<
  Awaited<ReturnType<typeof loadCloseRunForPack>>
>;
type ClosePackEvidenceItem = CloseRunForPack["evidenceItems"][number];
type ClosePackChecklistItem = CloseRunForPack["checklistItems"][number];
type ClosePackAuditExcerpt = Awaited<
  ReturnType<typeof loadClosePackAuditExcerpt>
>;

function evidenceText(item: ClosePackEvidenceItem) {
  return [
    item.evidenceType,
    item.sourceTable,
    item.sourceType,
    item.sourceId,
    item.sourceLabel,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function checklistText(item: ClosePackChecklistItem) {
  return [item.domain, item.key, item.label, item.detail]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function evidenceRefs(items: ClosePackEvidenceItem[]) {
  return items.map((item) => ({
    id: item.id,
    evidenceType: item.evidenceType,
    sourceTable: item.sourceTable,
    sourceType: item.sourceType,
    sourceId: item.sourceId,
    sourceLabel: item.sourceLabel,
    sourceDate: iso(item.sourceDate),
    sourceHash: item.sourceHash,
    provenance: item.provenance,
    available: item.available,
    correlationId: item.correlationId,
  }));
}

function matchedEvidence(run: CloseRunForPack, terms: string[]) {
  return run.evidenceItems.filter((item) => {
    const text = evidenceText(item);
    return terms.some((term) => text.includes(term));
  });
}

function matchedChecklist(run: CloseRunForPack, terms: string[]) {
  return run.checklistItems.filter((item) => {
    const text = checklistText(item);
    return terms.some((term) => text.includes(term));
  });
}

function availabilitySummary(
  label: string,
  evidenceItems: ClosePackEvidenceItem[],
  checklistItems: ClosePackChecklistItem[],
) {
  return {
    status:
      evidenceItems.length > 0 || checklistItems.length > 0
        ? "CAPTURED_IN_CLOSE_RUN"
        : "NOT_CAPTURED_IN_CLOSE_RUN",
    evidenceCount: evidenceItems.length,
    checklistGateCount: checklistItems.length,
    sourceHashes: evidenceItems
      .map((item) => item.sourceHash)
      .filter((hash): hash is string => Boolean(hash)),
    limitation:
      evidenceItems.length > 0 || checklistItems.length > 0
        ? null
        : `${label} evidence was not captured in this close-run snapshot.`,
  };
}

function closePackRowCount(
  run: CloseRunForPack,
  auditLogExcerpt: ClosePackAuditExcerpt,
) {
  return (
    run.checklistItems.length +
    run.findings.length +
    run.evidenceItems.length +
    run.reviews.length +
    run.comments.length +
    auditLogExcerpt.length
  );
}

function closePackEvidenceSummaries(
  run: CloseRunForPack,
  auditLogExcerpt: ClosePackAuditExcerpt,
) {
  const ledgerChecklist = matchedChecklist(run, ["ledger"]);
  const ledgerEvidence = matchedEvidence(run, ["ledger", "journal"]);
  const trialBalanceEvidence = matchedEvidence(run, [
    "trialbalance",
    "trial balance",
  ]);
  const reconciliationCertificates = run.evidenceItems.filter(
    (item) =>
      item.evidenceType === CloseEvidenceType.RECONCILIATION_CERTIFICATE,
  );
  const signedReconciliationCertificates = reconciliationCertificates.filter(
    (item) => item.sourceHash && item.provenance === "POSTED",
  );
  const suspenseEvidence = run.evidenceItems.filter(
    (item) => item.evidenceType === CloseEvidenceType.SUSPENSE_ITEM,
  );
  const openFindings = run.findings.filter((finding) =>
    OPEN_FINDING_STATUSES.includes(
      finding.status as (typeof OPEN_FINDING_STATUSES)[number],
    ),
  );
  const resolvedFindings = run.findings.filter(
    (finding) =>
      finding.status === CloseFindingStatus.RESOLVED ||
      finding.status === CloseFindingStatus.WAIVED_WITH_APPROVAL,
  );
  const arApTerms = [
    "accounts receivable",
    "accounts payable",
    "receivable",
    "payable",
    "ar",
    "ap",
  ];
  const taxVatTerms = ["tax", "vat", "tva", "declaration", "statutory"];
  const arApEvidence = matchedEvidence(run, arApTerms);
  const arApChecklist = matchedChecklist(run, arApTerms);
  const taxVatEvidence = matchedEvidence(run, taxVatTerms);
  const taxVatChecklist = matchedChecklist(run, taxVatTerms);
  const inventoryEvidence = matchedEvidence(run, ["inventory", "valuation"]);
  const inventoryChecklist = matchedChecklist(run, ["inventory", "valuation"]);

  return {
    dataTrust: {
      closeRunTrustLevel: closePackTrustLevelFromMetadata(run.metadata),
      draftMinimumTrustLevel: "T3",
      certifiedTargetTrustLevel: "T4",
    },
    ledgerReconciliationSummary: {
      checklistGateCount: ledgerChecklist.length,
      evidenceCount: ledgerEvidence.length,
      failedOrUnavailableHighRiskGateCount: ledgerChecklist.filter(
        (item) =>
          HIGH_RISK_CHECKLIST_STATUSES.includes(
            item.status as (typeof HIGH_RISK_CHECKLIST_STATUSES)[number],
          ) &&
          (item.severity === CloseFindingSeverity.CRITICAL ||
            item.severity === CloseFindingSeverity.HIGH),
      ).length,
      evidence: evidenceRefs(ledgerEvidence),
    },
    trialBalanceSummary: {
      evidenceCount: trialBalanceEvidence.length,
      hashes: trialBalanceEvidence
        .map((item) => item.sourceHash)
        .filter((hash): hash is string => Boolean(hash)),
      evidence: evidenceRefs(trialBalanceEvidence),
    },
    signedPaymentReconciliationRuns: evidenceRefs(
      signedReconciliationCertificates,
    ),
    reconciliationCertificateHashes: signedReconciliationCertificates
      .map((item) => item.sourceHash)
      .filter((hash): hash is string => Boolean(hash)),
    suspenseRegister: suspenseEvidence.map((item) => ({
      id: item.id,
      sourceTable: item.sourceTable,
      sourceType: item.sourceType,
      sourceId: item.sourceId,
      sourceLabel: item.sourceLabel,
      sourceDate: iso(item.sourceDate),
      sourceHash: item.sourceHash,
      available: item.available,
      unavailableReason: item.unavailableReason,
      correlationId: item.correlationId,
    })),
    exceptionSummary: {
      openFindingCount: openFindings.length,
      resolvedFindingCount: resolvedFindings.length,
      criticalOpenFindingCount: openFindings.filter(
        (finding) => finding.severity === CloseFindingSeverity.CRITICAL,
      ).length,
      highOpenFindingCount: openFindings.filter(
        (finding) => finding.severity === CloseFindingSeverity.HIGH,
      ).length,
    },
    arApSummary: availabilitySummary(
      "AR/AP",
      arApEvidence,
      arApChecklist,
    ),
    inventoryValuationSummary: availabilitySummary(
      "Inventory valuation",
      inventoryEvidence,
      inventoryChecklist,
    ),
    taxVatEvidenceSummary: availabilitySummary(
      "Tax/VAT",
      taxVatEvidence,
      taxVatChecklist,
    ),
    auditLogExcerpt: auditLogExcerpt.map((row) => ({
      id: row.id,
      action: row.action,
      actorId: row.actorId,
      resourceType: row.resourceType,
      resourceId: row.resourceId,
      message: row.message,
      metadata: redactSensitiveMetadata(row.metadata),
      createdAt: row.createdAt.toISOString(),
    })),
  };
}

