export async function exportClosePack(
  organizationId: string,
  input: ExportClosePackInput,
  control: ExportClosePackControl = {},
): Promise<ClosePackExportResult> {
  const now = control.now ? new Date(control.now) : new Date();
  const mode = exportMode(input);
  const correlationId = input.correlationId ?? randomUUID();
  const exportId = randomUUID();

  assertExportPermission(mode, control);
  if (mode === "CERTIFIED") requireFreshControl(control, now);

  const outcome = await db.$transaction<ClosePackExportResult | { blockedReason: string }>(async (tx) => {
    if (mode === "CERTIFIED") {
      const target = await tx.closeRun.findFirst({
        where: { id: input.closeRunId, organizationId, period: { organizationId } }, select: { periodId: true },
      });
      if (!target) throw new NotFoundError("Close run not found");
      await lockCloseAssessmentOrderInTx(tx, organizationId, target.periodId);
      await lockCloseRunEvidenceInTx(tx, organizationId, input.closeRunId);
    }
    const run = await loadCloseRunForPack(organizationId, input.closeRunId, tx);
    if (!run) throw new NotFoundError("Close run not found");

    if (mode === "CERTIFIED") {
      const order = await readCloseAssessmentOrderInTx(tx, organizationId, run.periodId);
      assertCloseAssessmentCurrent(deriveCloseAssessmentSelection(order, run));
      const settings = await tx.organizationAccountingSettings.findUnique({
        where: { organizationId },
        select: { accountingEnabled: true, setupStatus: true },
      });
      if (!settings?.accountingEnabled ||
          (settings.setupStatus !== "READY" && settings.setupStatus !== "LOCKED")) {
        throw new BusinessRuleError(
          "Certified close pack requires enabled accounting with READY or LOCKED setup. Complete accounting setup and run a new assessment.",
        );
      }
    }


    if (
      mode === "CERTIFIED" &&
      control.actorId &&
      run.runById === control.actorId
    ) {
      throw new BusinessRuleError(
        "The close runner cannot certify the same close pack.",
      );
    }

    const generatedAt = now.toISOString();
    const inventoryFreshness = await evaluateInventoryAnnexFreshness(
      run,
      tx,
      generatedAt,
    );
    const pilotCertification = await loadPilotCertificationEvidenceForCloseRun(
      run,
      tx,
    );
    const blockers = certificationBlockers(
      run,
      mode,
      inventoryFreshness,
      pilotCertification,
    );
    if (mode === "CERTIFIED" && blockers.length > 0) {
      if (
        inventoryFreshness.status !== "FRESH" &&
        metadataRecord(metadataRecord(run.metadata).staleState).status !== "EVIDENCE_STALE"
      ) {
        await recordCloseCertificationInvalidationInTx(
          tx,
          organizationId,
          {
            closeRunId: run.id,
            sourceModel: inventoryFreshness.sourceModel,
            sourceId: inventoryFreshness.sourceId,
            sourceEventName: inventoryFreshness.sourceEventName,
            staleReason:
              inventoryFreshness.staleReason ??
              inventoryFreshness.certificationBlocker ??
              "Close certification evidence is stale.",
            previousEvidenceHash: inventoryFreshness.previousEvidenceHash,
            newEvidenceHash: inventoryFreshness.newEvidenceHash,
            correlationId,
          },
          control,
          true,
        );
        // Commit the detected invalidation before returning the domain denial.
        // Retrying an already-invalidated run must retain its original evidence.
        return { blockedReason: blockers[0] };
      }
      throw new BusinessRuleError(
        `Certified close pack is blocked: ${blockers[0]}`,
      );
    }

    const auditLogExcerpt = await loadClosePackAuditExcerpt(
      tx,
      organizationId,
      run.id,
    );
    const rowCount = closePackRowCount(run, auditLogExcerpt);
    const watermarkId = `close-pack-${mode.toLowerCase().replaceAll("_", "-")}-${run.id}-${exportId.slice(0, 12)}`;
    const redactionNote =
      "Secrets, raw provider payloads, credentials, and tenant internals are excluded from this close pack.";
    const payload = buildClosePackPayload(run, {
      exportId,
      mode,
      generatedAt,
      generatedById: control.actorId ?? null,
      watermarkId,
      correlationId,
      redactionNote,
      certificationLimitations: certificationLimitations(mode),
      certificationBlockers: blockers,
      inventoryFreshness,
      pilotCertification,
      auditLogExcerpt,
    });
    const contentHash = sha256(stableStringify(payload));
    const content = JSON.stringify(
      { ...payload, export: { ...payload.export, contentHash } },
      null,
      2,
    );
    const fileName = `${watermarkId}.json`;
    const isCertified = mode === "CERTIFIED";

    const closePackExport = await tx.closePackExport.create({
      data: {
        organizationId,
        periodId: run.periodId,
        closeRunId: run.id,
        fileType: "json",
        watermarkId,
        contentHash,
        rowCount,
        isCertified,
        exportedById: control.actorId ?? null,
        exportedAt: now,
        correlationId,
        metadata: jsonObject({
          mode,
          trustLevel: closePackTrustLevelFromMetadata(run.metadata),
          certificationBlockers: blockers,
          inventoryValuationAnnex: inventoryFreshness.savedAnnex,
          inventoryAnnexFreshness: {
            status: inventoryFreshness.status,
            staleReason: inventoryFreshness.staleReason,
            previousEvidenceHash: inventoryFreshness.previousEvidenceHash,
            newEvidenceHash: inventoryFreshness.newEvidenceHash,
            detectedAt: inventoryFreshness.detectedAt,
          },
          pilotCycleCertification: pilotCertification.annex,
          statutoryCertification: statutoryCertificationBlockerMetadata(),
          redactionNote,
        }),
      },
    });

    if (inventoryFreshness.status !== "FRESH") {
      await recordInvalidationEvidenceInTx(
        tx,
        run,
        {
          closeRunId: run.id,
          closePackExportId: closePackExport.id,
          sourceModel: inventoryFreshness.sourceModel,
          sourceId: inventoryFreshness.sourceId,
          sourceEventName: inventoryFreshness.sourceEventName,
          staleReason:
            inventoryFreshness.staleReason ??
            inventoryFreshness.certificationBlocker ??
            "Close certification evidence is stale.",
          previousEvidenceHash: inventoryFreshness.previousEvidenceHash,
          newEvidenceHash: inventoryFreshness.newEvidenceHash,
          correlationId,
        },
        control,
      );
    }

    if (isCertified) {
      const existingMetadata = metadataRecord(run.metadata);
      await tx.closeRun.update({
        where: { id: run.id },
        data: {
          status: CloseRunStatus.CERTIFIED,
          metadata: jsonObject({
            ...existingMetadata,
            previousMetadata: run.metadata,
            certifiedExportId: closePackExport.id,
            certifiedContentHash: contentHash,
            certifiedAt: generatedAt,
            certifiedById: control.actorId ?? null,
            certificationLimitations: certificationLimitations(mode),
            inventoryAnnexFreshness: {
              status: inventoryFreshness.status,
              detectedAt: inventoryFreshness.detectedAt,
              previousEvidenceHash: inventoryFreshness.previousEvidenceHash,
              newEvidenceHash: inventoryFreshness.newEvidenceHash,
            },
            pilotCycleCertification: pilotCertification.annex,
            statutoryCertification: statutoryCertificationBlockerMetadata(),
          }),
        },
      });
    }

    await tx.ledgerAuditEvent.create({
      data: {
        organizationId,
        actorId: control.actorId ?? null,
        action: isCertified
          ? "CLOSE_PACK_CERTIFIED_EXPORT"
          : "CLOSE_PACK_DRAFT_EXPORT",
        resourceType: "ClosePackExport",
        resourceId: closePackExport.id,
        message: `Close pack ${watermarkId} exported`,
        metadata: jsonObject({
          closeRunId: run.id,
          periodId: run.periodId,
          mode,
          contentHash,
          watermarkId,
          rowCount,
          correlationId,
          certificationBlockers: blockers,
          inventoryAnnexFreshness: {
            status: inventoryFreshness.status,
            staleReason: inventoryFreshness.staleReason,
            previousEvidenceHash: inventoryFreshness.previousEvidenceHash,
            newEvidenceHash: inventoryFreshness.newEvidenceHash,
            detectedAt: inventoryFreshness.detectedAt,
          },
          pilotCycleCertification: pilotCertification.annex,
          statutoryCertification: statutoryCertificationBlockerMetadata(),
        }),
      },
    });

    return {
      exportId: closePackExport.id,
      closeRunId: run.id,
      periodId: run.periodId,
      fileName,
      mimeType: "application/json",
      content,
      contentHash,
      watermarkId,
      mode,
      isCertified,
      rowCount,
      generatedAt,
      correlationId,
      redactionNote,
      certificationLimitations: certificationLimitations(mode),
    };
  }, mode === "CERTIFIED" ? { isolationLevel: Prisma.TransactionIsolationLevel.ReadCommitted } : undefined);
  if ("blockedReason" in outcome) {
    throw new BusinessRuleError(`Certified close pack is blocked: ${outcome.blockedReason}`);
  }
  return outcome;
}

services/payments/provider-event.service:
import {
  ExceptionSeverity,
  PaymentExceptionStatus,
  PaymentExceptionType,
  PaymentReconciliationInboxSource,
  PaymentReconciliationInboxStatus,
  ProviderAccountStatus,
  ProviderEventStatus,
  Prisma,
} from "@prisma/client"
import { randomUUID } from "node:crypto"

import { AlertSeverity, AlertType, createAlert } from "@/lib/error-handling/monitoring"
import { logger } from "@/lib/logger"
import { db } from "@/prisma/db"
import { recordCloseCertificationInvalidationsForSourceInTx } from "@/services/accounting/close-assurance-pack.service"
import { recordBusinessEventInTx } from "@/services/events/business-event.service"

import type { ParsedProviderEvent, PaymentProviderAdapter, ProviderWebhookHeaders } from "./payment-ingestion.types"
import { PaymentIngestionError } from "./payment-ingestion.types"
import { sha256 } from "./adapters/mobile-money-hmac.adapter"

export type CaptureProviderEventInput = {
  organizationId: string
  providerAccountId?: string
  providerCode?: string
  adapter: PaymentProviderAdapter
  rawBody: string
  headers: ProviderWebhookHeaders
  secret: string
  receivedAt?: Date
  now?: Date
  correlationId?: string
}

export type CaptureProviderEventResult = {
  status: "CAPTURED" | "DUPLICATE" | "TAMPERED" | "REJECTED"
  providerEventId: string
  providerEventRecordId?: string
  inboxItemId?: string
  exceptionId?: string
  rawPayloadHash: string
  correlationId: string
}

function payloadSize(rawBody: string) {
  return Buffer.byteLength(rawBody, "utf8")
}

function firstHeader(headers: ProviderWebhookHeaders, name: string) {
  const value = headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()]
  return Array.isArray(value) ? value[0] : value
}

function signatureFailureReason(headers: ProviderWebhookHeaders, toleranceSeconds: number, now: Date) {
  if (!firstHeader(headers, "x-provider-signature")) return "MISSING_SIGNATURE" as const

  const timestamp = Number(firstHeader(headers, "x-provider-timestamp"))
  if (!Number.isFinite(timestamp)) return "INVALID_SIGNATURE" as const
  if (Math.abs(now.getTime() - timestamp) > toleranceSeconds * 1000) return "REPLAYED_EVENT" as const
  return "INVALID_SIGNATURE" as const
}

function toDecimal(value: Prisma.Decimal.Value | null | undefined) {
  return value === null || value === undefined ? null : new Prisma.Decimal(value)
}

function redactedProviderPayload(parsed: ParsedProviderEvent): Prisma.InputJsonObject {
  return {
    providerEventId: parsed.providerEventId,
    providerTransactionId: parsed.providerTransactionId ?? null,
    providerReference: parsed.providerReference ?? null,
    eventType: parsed.eventType,
    currencyCode: parsed.currencyCode ?? "XAF",
    occurredAt: parsed.occurredAt?.toISOString() ?? null,
  }
}

async function emitIngestionAlert(input: {
  organizationId: string
  providerAccountId: string
  providerEventId: string
  reason: string
  correlationId: string
}) {
  logger.warn("payment-reconciliation.provider-event.alert", input)
  await createAlert({
    type: AlertType.SECURITY,
    severity: AlertSeverity.HIGH,
    title: "Payment provider evidence alert",
    message: "Payment provider evidence failed ingestion controls.",
    source: "payment-reconciliation-ingestion",
    metadata: input,
  }).catch((error) => {
    logger.warn("payment-reconciliation.provider-event.alert_failed", {
      correlationId: input.correlationId,
      error: error instanceof Error ? error.message : "unknown",
    })
  })
}

export async function captureProviderEvent(input: CaptureProviderEventInput): Promise<CaptureProviderEventResult> {
  const correlationId = input.correlationId ?? randomUUID()
  const receivedAt = input.receivedAt ?? new Date()
  const now = input.now ?? receivedAt

  if (payloadSize(input.rawBody) > input.adapter.maxPayloadBytes) {
    throw new PaymentIngestionError("PAYLOAD_TOO_LARGE", "Provider payload exceeds the allowed size.", {
      correlationId,
      maxPayloadBytes: input.adapter.maxPayloadBytes,
    })
  }

  const parsed = input.adapter.parseEvent(input.rawBody, input.headers)
  const canonicalPayload = input.adapter.canonicalPayload(input.rawBody)
  const rawPayloadHash = sha256(canonicalPayload)
  const headersHash = sha256(JSON.stringify(input.headers))

  return db.$transaction(async (tx) => {
    const providerAccount = await tx.providerAccount.findFirst({
      where: {
        organizationId: input.organizationId,
        ...(input.providerAccountId ? { id: input.providerAccountId } : { providerCode: input.providerCode ?? input.adapter.providerCode }),
      },
      select: { id: true, status: true },
    })

    if (!providerAccount) {
      throw new PaymentIngestionError("PROVIDER_ACCOUNT_NOT_FOUND", "Provider account mapping was not found.", {
        correlationId,
      })
    }

    if (providerAccount.status !== ProviderAccountStatus.ACTIVE) {
      throw new PaymentIngestionError("PROVIDER_ACCOUNT_INACTIVE", "Provider account is not active for ingestion.", {
        correlationId,
        providerAccountId: providerAccount.id,
      })
    }

    const existing = await tx.providerEvent.findFirst({
      where: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        providerEventId: parsed.providerEventId,
      },
      select: { id: true, rawPayloadHash: true },
    })

    const inboxIdempotencyKey = sha256(`${providerAccount.id}|${parsed.providerEventId}|${rawPayloadHash}`)
    const signatureValid = input.adapter.verifySignature({
      rawBody: input.rawBody,
      headers: input.headers,
      secret: input.secret,
      now,
    })

    if (existing?.rawPayloadHash === rawPayloadHash) {
      const inbox = await tx.paymentReconciliationInboxItem.upsert({
        where: {
          organizationId_source_idempotencyKey: {
            organizationId: input.organizationId,
            source: PaymentReconciliationInboxSource.PROVIDER_EVENT,
            idempotencyKey: inboxIdempotencyKey,
          },
        },
        create: {
          organizationId: input.organizationId,
          providerAccountId: providerAccount.id,
          source: PaymentReconciliationInboxSource.PROVIDER_EVENT,
          status: PaymentReconciliationInboxStatus.IGNORED,
          idempotencyKey: inboxIdempotencyKey,
          externalId: parsed.providerEventId,
          payloadHash: rawPayloadHash,
          payloadSummary: redactedProviderPayload(parsed),
          processedAt: receivedAt,
          correlationId,
        },
        update: {
          attempts: { increment: 1 },
          processedAt: receivedAt,
          correlationId,
        },
        select: { id: true },
      })

      logger.info("payment-reconciliation.provider-event.duplicate", {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        providerEventId: parsed.providerEventId,
        correlationId,
      })

      return {
        status: "DUPLICATE",
        providerEventId: parsed.providerEventId,
        providerEventRecordId: existing.id,
        inboxItemId: inbox.id,
        rawPayloadHash,
        correlationId,
      }
    }

    if (existing && existing.rawPayloadHash !== rawPayloadHash) {
      const exception = await tx.paymentException.create({
        data: {
          organizationId: input.organizationId,
          providerAccountId: providerAccount.id,
          providerEventId: existing.id,
          type: PaymentExceptionType.TAMPER_SIGNAL,
          severity: ExceptionSeverity.CRITICAL,
          status: PaymentExceptionStatus.OPEN,
          sourceType: "ProviderEvent",
          sourceId: parsed.providerEventId,
          evidence: {
            existingPayloadHash: existing.rawPayloadHash,
            incomingPayloadHash: rawPayloadHash,
            correlationId,
          },
          correlationId,
        },
        select: { id: true },
      })

      await emitIngestionAlert({
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        providerEventId: parsed.providerEventId,
        reason: "TAMPERED_PROVIDER_EVENT",
        correlationId,
      })

      return {
        status: "TAMPERED",
        providerEventId: parsed.providerEventId,
        providerEventRecordId: existing.id,
        exceptionId: exception.id,
        rawPayloadHash,
        correlationId,
      }
    }

    const failureReason = signatureValid
      ? null
      : signatureFailureReason(input.headers, input.adapter.timestampToleranceSeconds, now)
    const rejectedStatus = failureReason === "REPLAYED_EVENT"
      ? ProviderEventStatus.REPLAYED
      : ProviderEventStatus.TAMPERED

    const event = await tx.providerEvent.create({
      data: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        providerEventId: parsed.providerEventId,
        providerTransactionId: parsed.providerTransactionId,
        providerReference: parsed.providerReference,
        eventType: parsed.eventType,
        status: signatureValid ? ProviderEventStatus.VERIFIED : rejectedStatus,
        direction: parsed.direction,
        amount: toDecimal(parsed.amount),
        feeAmount: toDecimal(parsed.feeAmount),
        currencyCode: parsed.currencyCode ?? "XAF",
        occurredAt: parsed.occurredAt,
        receivedAt,
        idempotencyKey: inboxIdempotencyKey,
        correlationId,
        rawPayload: parsed.rawPayload,
        redactedPayload: redactedProviderPayload(parsed),
        rawPayloadHash,
        headersHash,
        signatureHash: firstHeader(input.headers, "x-provider-signature")
          ? sha256(String(firstHeader(input.headers, "x-provider-signature")))
          : null,
        signatureValid,
        providerCustomerReferenceMasked: parsed.providerCustomerReferenceMasked,
        providerCustomerReferenceHash: parsed.providerCustomerReferenceHash,
      },
      select: { id: true },
    })

    const inbox = await tx.paymentReconciliationInboxItem.upsert({
      where: {
        organizationId_source_idempotencyKey: {
          organizationId: input.organizationId,
          source: PaymentReconciliationInboxSource.PROVIDER_EVENT,
          idempotencyKey: inboxIdempotencyKey,
        },
      },
      create: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        source: PaymentReconciliationInboxSource.PROVIDER_EVENT,
        status: signatureValid ? PaymentReconciliationInboxStatus.RECEIVED : PaymentReconciliationInboxStatus.FAILED,
        idempotencyKey: inboxIdempotencyKey,
        externalId: parsed.providerEventId,
        payloadHash: rawPayloadHash,
        payloadSummary: redactedProviderPayload(parsed),
        lastError: failureReason,
        correlationId,
      },
      update: {
        attempts: { increment: 1 },
        lastError: failureReason,
        correlationId,
      },
      select: { id: true },
    })

    if (!signatureValid) {
      const exception = await tx.paymentException.create({
        data: {
          organizationId: input.organizationId,
          providerAccountId: providerAccount.id,
          providerEventId: event.id,
          type: failureReason === "REPLAYED_EVENT" ? PaymentExceptionType.REPLAY_SPIKE : PaymentExceptionType.SIGNATURE_FAILURE,
          severity: ExceptionSeverity.CRITICAL,
          status: PaymentExceptionStatus.OPEN,
          sourceType: "ProviderEvent",
          sourceId: event.id,
          evidence: {
            failureReason,
            rawPayloadHash,
            correlationId,
          },
          correlationId,
        },
        select: { id: true },
      })

      await emitIngestionAlert({
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        providerEventId: parsed.providerEventId,
        reason: failureReason ?? "INVALID_SIGNATURE",
        correlationId,
      })

      await recordBusinessEventInTx(tx, {
        organizationId: input.organizationId,
        eventType: "payment.provider_event.rejected",
        eventSource: "PROVIDER_WEBHOOK",
        idempotencyKey: `provider-event:${event.id}:rejected`,
        sourceType: "PAYMENT_RECONCILIATION",
        sourceId: event.id,
        documentHash: rawPayloadHash,
        payload: {
          providerEventRecordId: event.id,
          providerEventId: parsed.providerEventId,
          providerTransactionId: parsed.providerTransactionId ?? null,
          providerReference: parsed.providerReference ?? null,
          providerAccountId: providerAccount.id,
          inboxItemId: inbox.id,
          exceptionId: exception.id,
          status: rejectedStatus,
          failureReason,
          rawPayloadHash,
          headersHash,
          correlationId,
        },
        outboxMessages: [
          {
            channel: "NOTIFICATION",
            eventName: "payment.provider_event.rejected",
            payload: {
              providerEventRecordId: event.id,
              providerEventId: parsed.providerEventId,
              providerAccountId: providerAccount.id,
              exceptionId: exception.id,
              failureReason,
              correlationId,
            },
          },
        ],
      })

      return {
        status: "REJECTED",
        providerEventId: parsed.providerEventId,
        providerEventRecordId: event.id,
        inboxItemId: inbox.id,
        exceptionId: exception.id,
        rawPayloadHash,
        correlationId,
      }
    }

    logger.info("payment-reconciliation.provider-event.captured", {
      organizationId: input.organizationId,
      providerAccountId: providerAccount.id,
      providerEventId: parsed.providerEventId,
      correlationId,
    })

    await recordBusinessEventInTx(tx, {
      organizationId: input.organizationId,
      eventType: "payment.provider_event.captured",
      eventSource: "PROVIDER_WEBHOOK",
      idempotencyKey: `provider-event:${event.id}:captured`,
      sourceType: "PAYMENT_RECONCILIATION",
      sourceId: event.id,
      documentHash: rawPayloadHash,
      payload: {
        providerEventRecordId: event.id,
        providerEventId: parsed.providerEventId,
        providerTransactionId: parsed.providerTransactionId ?? null,
        providerReference: parsed.providerReference ?? null,
        providerAccountId: providerAccount.id,
        inboxItemId: inbox.id,
        eventType: parsed.eventType,
        direction: parsed.direction,
        amount: parsed.amount === null || parsed.amount === undefined ? null : String(parsed.amount),
        feeAmount: parsed.feeAmount === null || parsed.feeAmount === undefined ? null : String(parsed.feeAmount),
        currencyCode: parsed.currencyCode ?? "XAF",
        occurredAt: parsed.occurredAt,
        receivedAt,
        rawPayloadHash,
        headersHash,
        signatureValid,
        correlationId,
      },
      outboxMessages: [
        {
          channel: "NOTIFICATION",
          eventName: "payment.provider_event.captured",
          payload: {
            providerEventRecordId: event.id,
            providerEventId: parsed.providerEventId,
            providerAccountId: providerAccount.id,
            inboxItemId: inbox.id,
            amount: parsed.amount === null || parsed.amount === undefined ? null : String(parsed.amount),
            currencyCode: parsed.currencyCode ?? "XAF",
            correlationId,
          },
        },
      ],
    })

    await recordCloseCertificationInvalidationsForSourceInTx(tx, input.organizationId, {
      sourceCode: "PAYMENT_PROVIDER_EVENT_CAPTURED",
      sourceId: event.id,
      periodStart: parsed.occurredAt ?? receivedAt,
      periodEnd: parsed.occurredAt ?? receivedAt,
      staleReason: "Provider event capture changed certified close evidence.",
      newEvidenceHash: rawPayloadHash,
      correlationId,
    })

    return {
      status: "CAPTURED",
      providerEventId: parsed.providerEventId,
      providerEventRecordId: event.id,
      inboxItemId: inbox.id,
      rawPayloadHash,
      correlationId,
    }
  })
}

services/payments/statement-import.servi:
import {
  ExceptionSeverity,
  PaymentExceptionStatus,
  PaymentExceptionType,
  PaymentReconciliationInboxSource,
  PaymentReconciliationInboxStatus,
  ProviderAccountStatus,
  StatementFileStatus,
  StatementLineStatus,
  Prisma,
} from "@prisma/client"
import { randomUUID } from "node:crypto"

import { logger } from "@/lib/logger"
import { db } from "@/prisma/db"
import { recordCloseCertificationInvalidationsForSourceInTx } from "@/services/accounting/close-assurance-pack.service"
import { recordBusinessEventInTx } from "@/services/events/business-event.service"
import { assertModuleNewWorkInTx } from "@/services/modules/module-admission.service"

import type { ParsedStatementLine, PaymentProviderAdapter } from "./payment-ingestion.types"
import { PaymentIngestionError } from "./payment-ingestion.types"
import { sha256 } from "./adapters/mobile-money-hmac.adapter"

export type ImportProviderStatementInput = {
  organizationId: string
  providerAccountId: string
  adapter: PaymentProviderAdapter
  rawContent: string
  fileName?: string
  importedById?: string
  correlationId?: string
  maxFileBytes?: number
}

export type ImportProviderStatementResult = {
  status: "IMPORTED" | "DUPLICATE_FILE" | "DUPLICATE_LINE"
  statementFileId?: string
  importedLineCount: number
  duplicateLineCount: number
  fileHash: string
  inboxItemId?: string
  exceptionId?: string
  correlationId: string
}

function payloadSize(rawContent: string) {
  return Buffer.byteLength(rawContent, "utf8")
}

function toDecimal(value: Prisma.Decimal.Value | null | undefined) {
  return value === null || value === undefined ? null : new Prisma.Decimal(value)
}

function lineHash(line: ParsedStatementLine, fingerprint: string) {
  return sha256(
    JSON.stringify({
      fingerprint,
      providerTransactionId: line.providerTransactionId,
      providerReference: line.providerReference,
      amount: String(line.amount),
      currencyCode: line.currencyCode ?? "XAF",
      occurredAt: line.occurredAt.toISOString(),
    }),
  )
}

function duplicateFingerprints(lines: Array<{ fingerprint: string }>) {
  const seen = new Set<string>()
  const duplicates = new Set<string>()

  for (const line of lines) {
    if (seen.has(line.fingerprint)) duplicates.add(line.fingerprint)
    seen.add(line.fingerprint)
  }

  return duplicates
}

export async function importProviderStatement(
  input: ImportProviderStatementInput,
): Promise<ImportProviderStatementResult> {
  const correlationId = input.correlationId ?? randomUUID()
  const maxFileBytes = input.maxFileBytes ?? 5 * 1024 * 1024

  if (payloadSize(input.rawContent) > maxFileBytes) {
    throw new PaymentIngestionError("PAYLOAD_TOO_LARGE", "Statement file exceeds the allowed size.", {
      correlationId,
      maxFileBytes,
    })
  }

  const parsed = input.adapter.parseStatement({
    rawContent: input.rawContent,
    fileName: input.fileName,
  })
  const fileHash = sha256(input.rawContent)
  if (parsed.lines.length === 0) {
    throw new PaymentIngestionError(
      "INVALID_PAYLOAD",
      "Statement file did not contain importable lines.",
      {
        correlationId,
        providerCode: input.adapter.providerCode,
        fileHash,
      },
    )
  }
  const preparedLines = parsed.lines.map((line) => {
    const fingerprint = input.adapter.fingerprintStatementLine(line)
    return {
      line,
      fingerprint,
      rawLineHash: line.rawLineHash ?? lineHash(line, fingerprint),
    }
  })
  const duplicateInFile = duplicateFingerprints(preparedLines)

  return db.$transaction(async (tx) => {
    // Read provider status after acquiring the lock, including when another import held it.
    await tx.$queryRaw(Prisma.sql`SELECT "id" FROM "provider_accounts" WHERE "id" = ${input.providerAccountId} AND "organizationId" = ${input.organizationId} FOR UPDATE`)
    const providerAccount = await tx.providerAccount.findFirst({
      where: {
        id: input.providerAccountId,
        organizationId: input.organizationId,
      },
      select: { id: true, status: true },
    })

    if (!providerAccount) {
      throw new PaymentIngestionError("PROVIDER_ACCOUNT_NOT_FOUND", "Provider account mapping was not found.", {
        correlationId,
      })
    }

    if (providerAccount.status !== ProviderAccountStatus.ACTIVE) {
      throw new PaymentIngestionError("PROVIDER_ACCOUNT_INACTIVE", "Provider account is not active for ingestion.", {
        correlationId,
        providerAccountId: providerAccount.id,
      })
    }

    // Serialize imports for this provider, including rejected duplicate files, so retries cannot create duplicate cases.
    const priorDuplicate = await tx.paymentException.findFirst({ where: { organizationId: input.organizationId, providerAccountId: providerAccount.id,
      type: PaymentExceptionType.DUPLICATE_PROVIDER_REFERENCE, sourceType: { in: ["StatementFile", "StatementLine"] }, evidence: { path: ["fileHash"], equals: fileHash } },
      select: { id: true, evidence: true }, orderBy: [{ createdAt: "asc" }, { id: "asc" }] })
    if (priorDuplicate) {
      const evidence = priorDuplicate.evidence as { duplicateFingerprints?: unknown }
      if (!Array.isArray(evidence?.duplicateFingerprints) || !evidence.duplicateFingerprints.length || evidence.duplicateFingerprints.some(value => typeof value !== "string"))
        throw new PaymentIngestionError("INVALID_PAYLOAD", "Retained duplicate statement evidence requires review.")
      return { status: "DUPLICATE_LINE", importedLineCount: 0, duplicateLineCount: evidence.duplicateFingerprints.length,
        fileHash, exceptionId: priorDuplicate.id, correlationId }
    }
    const existingFile = await tx.statementFile.findFirst({
      where: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        fileHash,
      },
      select: { id: true },
    })

    if (existingFile) {
      const inbox = await tx.paymentReconciliationInboxItem.upsert({
        where: {
          organizationId_source_idempotencyKey: {
            organizationId: input.organizationId,
            source: PaymentReconciliationInboxSource.STATEMENT_FILE,
            idempotencyKey: fileHash,
          },
        },
        create: {
          organizationId: input.organizationId,
          providerAccountId: providerAccount.id,
          source: PaymentReconciliationInboxSource.STATEMENT_FILE,
          status: PaymentReconciliationInboxStatus.IGNORED,
          idempotencyKey: fileHash,
          externalId: input.fileName,
          payloadHash: fileHash,
          payloadSummary: {
            fileName: input.fileName ?? null,
            sourceType: parsed.sourceType,
            lineCount: parsed.lines.length,
          },
          processedAt: new Date(),
          correlationId,
        },
        update: {
          attempts: { increment: 1 },
          processedAt: new Date(),
          correlationId,
        },
        select: { id: true },
      })

      logger.info("payment-reconciliation.statement.duplicate-file", {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        fileName: input.fileName,
        correlationId,
      })

      return {
        status: "DUPLICATE_FILE",
        statementFileId: existingFile.id,
        importedLineCount: 0,
        duplicateLineCount: parsed.lines.length,
        fileHash,
        inboxItemId: inbox.id,
        correlationId,
      }
    }

    await assertModuleNewWorkInTx(tx, { organizationId: input.organizationId, moduleSlug: "payment_reconciliation", operation: "payment.statement.import" })
    if (duplicateInFile.size > 0) {
      const exception = await tx.paymentException.create({
        data: {
          organizationId: input.organizationId,
          providerAccountId: providerAccount.id,
          type: PaymentExceptionType.DUPLICATE_PROVIDER_REFERENCE,
          severity: ExceptionSeverity.HIGH,
          status: PaymentExceptionStatus.OPEN,
          sourceType: "StatementFile",
          sourceId: input.fileName ?? fileHash,
          evidence: {
            fileHash,
            duplicateFingerprints: [...duplicateInFile],
            correlationId,
          },
          correlationId,
        },
        select: { id: true },
      })

      return {
        status: "DUPLICATE_LINE",
        importedLineCount: 0,
        duplicateLineCount: duplicateInFile.size,
        fileHash,
        exceptionId: exception.id,
        correlationId,
      }
    }

    const existingLines = await tx.statementLine.findMany({
      where: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        fingerprint: { in: preparedLines.map((line) => line.fingerprint) },
      },
      select: { fingerprint: true },
    })

    if (existingLines.length > 0) {
      const exception = await tx.paymentException.create({
        data: {
          organizationId: input.organizationId,
          providerAccountId: providerAccount.id,
          type: PaymentExceptionType.DUPLICATE_PROVIDER_REFERENCE,
          severity: ExceptionSeverity.HIGH,
          status: PaymentExceptionStatus.OPEN,
          sourceType: "StatementLine",
          sourceId: input.fileName ?? fileHash,
          evidence: {
            fileHash,
            duplicateFingerprints: existingLines.map((line) => line.fingerprint),
            correlationId,
          },
          correlationId,
        },
        select: { id: true },
      })

      return {
        status: "DUPLICATE_LINE",
        importedLineCount: 0,
        duplicateLineCount: existingLines.length,
        fileHash,
        exceptionId: exception.id,
        correlationId,
      }
    }

    const statementFile = await tx.statementFile.create({
      data: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        sourceType: parsed.sourceType,
        fileName: input.fileName,
        fileHash,
        periodStart: parsed.periodStart ?? parsed.lines[0].occurredAt,
        periodEnd: parsed.periodEnd ?? parsed.lines[parsed.lines.length - 1].occurredAt,
        status: StatementFileStatus.IMPORTED,
        importedById: input.importedById,
        correlationId,
        metadata: {
          lineCount: parsed.lines.length,
          adapter: input.adapter.providerCode,
        },
      },
      select: { id: true },
    })

    await tx.statementLine.createMany({
      data: preparedLines.map(({ line, fingerprint, rawLineHash }) => ({
        organizationId: input.organizationId,
        statementFileId: statementFile.id,
        providerAccountId: providerAccount.id,
        fingerprint,
        lineNumber: line.lineNumber,
        providerTransactionId: line.providerTransactionId,
        providerReference: line.providerReference,
        direction: line.direction ?? "UNKNOWN",
        status: StatementLineStatus.UNMATCHED,
        amount: new Prisma.Decimal(line.amount),
        feeAmount: toDecimal(line.feeAmount),
        currencyCode: line.currencyCode ?? "XAF",
        occurredAt: line.occurredAt,
        postedAt: line.postedAt,
        description: line.description,
        counterpartyMasked: line.counterpartyMasked,
        counterpartyHash: line.counterpartyHash,
        rawLineHash,
        metadata: line.metadata ?? Prisma.JsonNull,
      })),
    })

    const inbox = await tx.paymentReconciliationInboxItem.upsert({
      where: {
        organizationId_source_idempotencyKey: {
          organizationId: input.organizationId,
          source: PaymentReconciliationInboxSource.STATEMENT_FILE,
          idempotencyKey: fileHash,
        },
      },
      create: {
        organizationId: input.organizationId,
        providerAccountId: providerAccount.id,
        source: PaymentReconciliationInboxSource.STATEMENT_FILE,
        status: PaymentReconciliationInboxStatus.RECEIVED,
        idempotencyKey: fileHash,
        externalId: input.fileName,
        payloadHash: fileHash,
        payloadSummary: {
          fileName: input.fileName ?? null,
          sourceType: parsed.sourceType,
          lineCount: parsed.lines.length,
        },
        correlationId,
      },
      update: {
        attempts: { increment: 1 },
        correlationId,
      },
      select: { id: true },
    })

    logger.info("payment-reconciliation.statement.imported", {
      organizationId: input.organizationId,
      providerAccountId: providerAccount.id,
      statementFileId: statementFile.id,
      lineCount: parsed.lines.length,
      correlationId,
    })

    await recordBusinessEventInTx(tx, {
      organizationId: input.organizationId,
      eventType: "payment.statement.imported",
      eventSource: "IMPORT",
      idempotencyKey: `statement-file:${statementFile.id}:imported`,
      actorId: input.importedById,
      sourceType: "PAYMENT_RECONCILIATION",
      sourceId: statementFile.id,
      documentHash: fileHash,
      payload: {
        statementFileId: statementFile.id,
        providerAccountId: providerAccount.id,
        inboxItemId: inbox.id,
        sourceType: parsed.sourceType,
        fileName: input.fileName ?? null,
        fileHash,
        lineCount: parsed.lines.length,
        periodStart: parsed.periodStart ?? parsed.lines[0].occurredAt,
        periodEnd: parsed.periodEnd ?? parsed.lines[parsed.lines.length - 1].occurredAt,
        adapter: input.adapter.providerCode,
        correlationId,
      },
      outboxMessages: [
        {
          channel: "NOTIFICATION",
          eventName: "payment.statement.imported",
          payload: {
            statementFileId: statementFile.id,
            providerAccountId: providerAccount.id,
            inboxItemId: inbox.id,
            fileName: input.fileName ?? null,
            lineCount: parsed.lines.length,
            correlationId,
          },
        },
      ],
    })
    await recordCloseCertificationInvalidationsForSourceInTx(tx, input.organizationId, {
      sourceCode: "PAYMENT_STATEMENT_IMPORT",
      sourceId: statementFile.id,
      periodStart: parsed.periodStart ?? parsed.lines[0].occurredAt,
      periodEnd: parsed.periodEnd ?? parsed.lines[parsed.lines.length - 1].occurredAt,
      staleReason: "Provider statement import changed payment evidence after close certification.",
      newEvidenceHash: fileHash,
      correlationId,
    }, {
      actorId: input.importedById ?? null,
    })

    return {
      status: "IMPORTED",
      statementFileId: statementFile.id,
      importedLineCount: parsed.lines.length,
      duplicateLineCount: 0,
      fileHash,
      inboxItemId: inbox.id,
      correlationId,
    }
  })
}
